fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Cast to i16 to avoid overflow when computing difference
    let diff = (a as i16 - b as i16).abs();
    diff < (tol as i16)
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Arrays have equal, non-zero length per problem statement
    let mut result = Vec::with_capacity(a.len());
    
    for i in 0..a.len() {
        result.push(is_close_i8(a[i], b[i], tol));
    }
    
    result
}